.ds-button-primary{display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;gap:6px;height:32px;min-height:32px;padding:0 10px;border:1px solid transparent;border-radius:0;font:400 14px/1.5 'Inter Variable',sans-serif;white-space:nowrap;cursor:pointer;user-select:none;outline:none;transition:all 150ms cubic-bezier(0.4,0,0.2,1);}
.ds-button-primary svg{width:16px;height:16px;flex-shrink:0;pointer-events:none;}
.ds-button-primary:focus-visible{border-color:var(--ring,oklch(0.556 0 0));box-shadow:0 0 0 1px color-mix(in oklab,var(--ring,oklch(0.556 0 0)) 50%,transparent);}
.ds-button-primary:active:not([aria-haspopup]){transform:translateY(1px);}
.ds-button-primary:disabled{pointer-events:none;opacity:.5;cursor:not-allowed;}
@media(max-width:680px),(pointer:coarse){.ds-button-primary{min-height:44px;}}
@media(max-width:680px){.ds-button-primary{font-size:16px;}}
@media(prefers-reduced-motion:reduce){.ds-button-primary{transition:none;}}
.ds-button-primary{background:var(--primary,oklch(0.459 0.187 3.815));color:var(--primary-foreground,oklch(0.971 0.014 343.198));}
.ds-button-primary:hover{background:color-mix(in oklab,var(--primary,oklch(0.459 0.187 3.815)) 80%,transparent);}

