.ds-button-outline{background:color-mix(in oklab,var(--input,oklch(1 0 0 / 15%)) 30%,transparent);border-color:var(--input,oklch(1 0 0 / 15%));color:var(--foreground,oklch(0.985 0 0));}
.ds-button-outline:hover{background:color-mix(in oklab,var(--input,oklch(1 0 0 / 15%)) 50%,transparent);}
