.ds-button-ghost[aria-expanded=true]{background:var(--muted,oklch(0.269 0 0));color:var(--foreground,oklch(0.985 0 0));}
:host-context(.light) .ds-button-ghost:hover{background:var(--muted,oklch(0.269 0 0));}

.ds-button-destructive{display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;gap:6px;height:32px;min-height:32px;padding:0 10px;border:1px solid transparent;border-radius:0;font:400 14px/1.5 'Inter Variable',sans-serif;white-space:nowrap;cursor:pointer;user-select:none;outline:none;transition:all 150ms cubic-bezier(0.4,0,0.2,1);}
.ds-button-destructive svg{width:16px;height:16px;flex-shrink:0;pointer-events:none;}
.ds-button-destructive:focus-visible{border-color:var(--ring,oklch(0.556 0 0));box-shadow:0 0 0 1px color-mix(in oklab,var(--ring,oklch(0.556 0 0)) 50%,transparent);}
.ds-button-destructive:active:not([aria-haspopup]){transform:translateY(1px);}
.ds-button-destructive:disabled{pointer-events:none;opacity:.5;cursor:not-allowed;}
@media(max-width:680px),(pointer:coarse){.ds-button-destructive{min-height:44px;}}
@media(max-width:680px){.ds-button-destructive{font-size:16px;}}
