.ds-button-destructive{background:color-mix(in oklab,var(--destructive,oklch(0.704 0.191 22.216)) 20%,transparent);color:var(--destructive,oklch(0.704 0.191 22.216));}
.ds-button-destructive:hover{background:color-mix(in oklab,var(--destructive,oklch(0.704 0.191 22.216)) 30%,transparent);}
.ds-button-destructive:focus-visible{border-color:color-mix(in oklab,var(--destructive,oklch(0.704 0.191 22.216)) 40%,transparent);box-shadow:0 0 0 1px color-mix(in oklab,var(--destructive,oklch(0.704 0.191 22.216)) 40%,transparent);}
:host-context(.light) .ds-button-destructive{background:color-mix(in oklab,var(--destructive,oklch(0.704 0.191 22.216)) 10%,transparent);}
:host-context(.light) .ds-button-destructive:hover{background:color-mix(in oklab,var(--destructive,oklch(0.704 0.191 22.216)) 20%,transparent);}
:host-context(.light) .ds-button-destructive:focus-visible{box-shadow:0 0 0 1px color-mix(in oklab,var(--destructive,oklch(0.704 0.191 22.216)) 20%,transparent);}

.ds-input{width:100%;min-width:0;height:32px;min-height:32px;padding:4px 10px;border:1px solid var(--input,oklch(1 0 0 / 15%));border-radius:0;background:color-mix(in oklab,var(--input,oklch(1 0 0 / 15%)) 30%,transparent);color:var(--foreground,oklch(0.985 0 0));font:400 14px/1.5 'Inter Variable',sans-serif;outline:none;transition:color 150ms cubic-bezier(0.4,0,0.2,1),background-color 150ms cubic-bezier(0.4,0,0.2,1),border-color 150ms cubic-bezier(0.4,0,0.2,1);}
.ds-input::placeholder{color:var(--muted-foreground,oklch(0.708 0 0));}
.ds-input:focus-visible{border-color:var(--ring,oklch(0.556 0 0));box-shadow:0 0 0 1px color-mix(in oklab,var(--ring,oklch(0.556 0 0)) 50%,transparent);}
.ds-input:disabled{pointer-events:none;cursor:not-allowed;opacity:.5;background:color-mix(in oklab,var(--input,oklch(1 0 0 / 15%)) 80%,transparent);}
.ds-input[aria-invalid=true]{border-color:color-mix(in oklab,var(--destructive,oklch(0.704 0.191 22.216)) 50%,transparent);box-shadow:0 0 0 1px color-mix(in oklab,var(--destructive,oklch(0.704 0.191 22.216)) 40%,transparent);}
:host-context(.light) .ds-input{background:transparent;}
:host-context(.light) .ds-input:disabled{background:color-mix(in oklab,var(--input,oklch(1 0 0 / 15%)) 50%,transparent);}
:host-context(.light) .ds-input[aria-invalid=true]{border-color:var(--destructive,oklch(0.704 0.191 22.216));box-shadow:0 0 0 1px color-mix(in oklab,var(--destructive,oklch(0.704 0.191 22.216)) 20%,transparent);}
@media(max-width:680px),(pointer:coarse){.ds-input{min-height:44px;}}
@media(max-width:680px){.ds-input{font-size:16px;}}
@media(prefers-reduced-motion:reduce){.ds-input{transition:none;}}

.ds-connection-card{min-width:0;padding:14px 16px 6px;border:1px solid var(--border,oklch(1 0 0 / 10%));border-radius:4px;background:var(--card,oklch(0.205 0 0));color:var(--foreground,oklch(0.985 0 0));font:400 14px/1.5 'Inter Variable',sans-serif;}
.ds-connection-heading h2{margin:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:600 15px/1.4 'Inter Variable',sans-serif;}
.ds-connection-heading>span{color:var(--muted-foreground,oklch(0.708 0 0));font-size:11px;}
.ds-connection-url{display:block;margin:14px 0 10px;padding:8px 10px;border:1px solid var(--border,oklch(1 0 0 / 10%));background:var(--background,oklch(0.145 0 0));font:400 12px/1.6 ui-monospace,monospace;overflow-wrap:anywhere;}
.ds-connection-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:40px;padding-top:7px;border-top:1px solid var(--border,oklch(1 0 0 / 10%));}
.ds-connection-footer>span{font-size:11px;color:var(--muted-foreground,oklch(0.708 0 0));}
.ds-connection-edit{display:inline-flex;align-items:center;justify-content:center;min-height:32px;padding:0 10px;border:1px solid transparent;border-radius:0;background:transparent;color:var(--foreground,oklch(0.985 0 0));font:400 14px/1.5 'Inter Variable',sans-serif;cursor:pointer;outline:none;transition:all 150ms cubic-bezier(0.4,0,0.2,1);}
.ds-connection-edit:hover{background:color-mix(in oklab,var(--muted,oklch(0.269 0 0)) 50%,transparent);}
.ds-connection-edit:focus-visible{border-color:var(--ring,oklch(0.556 0 0));box-shadow:0 0 0 1px color-mix(in oklab,var(--ring,oklch(0.556 0 0)) 50%,transparent);}
.ds-connection-edit:active{transform:translateY(1px);}
:host-context(.light) .ds-connection-edit:hover{background:var(--muted,oklch(0.269 0 0));}
@media(max-width:680px),(pointer:coarse){.ds-connection-edit{min-height:44px;}}
@media(prefers-reduced-motion:reduce){.ds-connection-edit{transition:none;}}

.ds-state-format{display:inline-flex;align-items:center;gap:2px;width:fit-content;height:32px;margin:0;padding:2px;border:1px solid var(--border,oklch(1 0 0 / 10%));border-radius:0;background:var(--card,oklch(0.205 0 0));color:var(--foreground,oklch(0.985 0 0));font:400 14px/1.5 'Inter Variable',sans-serif;}
.ds-state-option{position:relative;display:inline-flex;}
.ds-state-radio{position:absolute;width:1px;height:1px;margin:0;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap;}
.ds-state-label{display:inline-flex;align-items:center;justify-content:center;height:26px;min-width:46px;padding:0 8px;border-radius:0;background:transparent;cursor:pointer;transition:color 150ms cubic-bezier(0.4,0,0.2,1),background-color 150ms cubic-bezier(0.4,0,0.2,1);}
.ds-state-label:hover,.ds-state-radio:checked+.ds-state-label{background:var(--muted,oklch(0.269 0 0));color:var(--foreground,oklch(0.985 0 0));}
.ds-state-radio:focus-visible+.ds-state-label{box-shadow:0 0 0 3px color-mix(in oklab,var(--ring,oklch(0.556 0 0)) 50%,transparent);}
.ds-state-radio:disabled+.ds-state-label{pointer-events:none;opacity:.5;}
@media(max-width:680px),(pointer:coarse){.ds-state-format{height:50px;}.ds-state-label{height:44px;min-width:44px;}}
@media(max-width:680px){.ds-state-format{font-size:16px;}}
@media(prefers-reduced-motion:reduce){.ds-state-label{transition:none;}}

.ds-question{position:relative;min-width:0;border:1px solid var(--border,oklch(1 0 0 / 10%));border-radius:4px;background:var(--background,oklch(0.145 0 0));color:var(--foreground,oklch(0.985 0 0));font:400 14px/1.5 'Inter Variable',sans-serif;}
.ds-question-summary{display:flex;align-items:center;gap:10px;min-height:40px;padding:6px 44px 6px 10px;list-style:none;cursor:pointer;}
.ds-question-summary::-webkit-details-marker{display:none;}
.ds-question-summary:focus-visible{outline-offset:4px;}
.ds-question-summary code{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:400 13px/1.5 ui-monospace,'SFMono-Regular',Consolas,monospace;}
.ds-question-badge{display:inline-flex;align-items:center;height:20px;padding:2px 8px;border:1px solid var(--border,oklch(1 0 0 / 10%));border-radius:0;font:400 11px/1.333333 'Inter Variable',sans-serif;white-space:nowrap;}
.ds-question-chevron{width:14px;height:14px;flex-shrink:0;color:var(--muted-foreground,oklch(0.708 0 0));}
.ds-question-details[open] .ds-question-chevron{transform:rotate(180deg);}
.ds-question-content{padding:4px 12px 12px;}
.ds-question-label{display:block;margin-bottom:6px;color:var(--muted-foreground,oklch(0.708 0 0));font-size:12px;}
.ds-question-input{width:100%;min-width:0;height:32px;min-height:32px;padding:4px 10px;border:1px solid var(--input,oklch(1 0 0 / 15%));border-radius:3px;background:color-mix(in oklab,var(--input,oklch(1 0 0 / 15%)) 30%,transparent);color:var(--foreground,oklch(0.985 0 0));font:400 14px/1.5 'Inter Variable',sans-serif;outline:none;transition:color 150ms cubic-bezier(0.4,0,0.2,1),background-color 150ms cubic-bezier(0.4,0,0.2,1),border-color 150ms cubic-bezier(0.4,0,0.2,1);}
.ds-question-input:focus-visible{border-color:var(--ring,oklch(0.556 0 0));box-shadow:0 0 0 1px color-mix(in oklab,var(--ring,oklch(0.556 0 0)) 50%,transparent);}
.ds-question-remove{position:absolute;top:4px;right:4px;display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;padding:0;border:1px solid transparent;border-radius:0;background:transparent;color:var(--muted-foreground,oklch(0.708 0 0));cursor:pointer;outline:none;transition:all 150ms cubic-bezier(0.4,0,0.2,1);}
.ds-question-remove svg{width:16px;height:16px;pointer-events:none;}
.ds-question-remove:hover{background:color-mix(in oklab,var(--muted,oklch(0.269 0 0)) 50%,transparent);color:var(--destructive,oklch(0.704 0.191 22.216));}
.ds-question-remove:focus-visible{border-color:var(--ring,oklch(0.556 0 0));box-shadow:0 0 0 1px color-mix(in oklab,var(--ring,oklch(0.556 0 0)) 50%,transparent);}
.ds-question-remove:active{transform:translateY(1px);}
:host-context(.light) .ds-question-input{background:transparent;}
:host-context(.light) .ds-question-remove:hover{background:var(--muted,oklch(0.269 0 0));}
@media(max-width:680px),(pointer:coarse){.ds-question-summary{min-height:48px;padding-right:52px;}.ds-question-remove{top:2px;right:2px;width:44px;height:44px;}.ds-question-input{min-height:44px;}}
@media(max-width:680px){.ds-question-summary code{font-size:12px;}.ds-question-badge{font-size:10px;}.ds-question-input{font-size:16px;}}
@media(prefers-reduced-motion:reduce){.ds-question-input,.ds-question-remove{transition:none;}}
